function POWER-SUM-MOD(N, k):
    S <- 0
    for a <- 1 to N:
        S <- (S + a^k mod N) mod N        # square-and-multiply
    return S

function READOUT(N, k):
    return gcd(POWER-SUM-MOD(N, k), N)     # always a divisor of N

function POWER-SUM-FACTOR-SEARCH(N):
    for k <- 1, 2, 3, ...:
        d <- READOUT(N, k)
        if 1 < d < N:
            return d                        # a proper prime factor
        # invariant: d = prod { r prime : r | N, (r-1) does not divide k }
        # for N = pq the loop first exits at k = min(p-1, q-1)

function READ-CARMICHAEL(N):
    for k <- 1, 2, 3, ...:
        if gcd(POWER-SUM-MOD(N,k), N) = 1:
            return k                        # = lambda(N), the least period

function RECOVER-FACTORS(N, lambda):
    for each divisor g of lambda:            # g is the ambiguity gcd(p-1,q-1)
        s <- N + 1 - lambda * g              # candidate value of p + q
        if s <= 0: continue
        D <- s^2 - 4N
        if D < 0 or D is not a perfect square: continue
        p <- (s + sqrt(D)) / 2 ;  q <- (s - sqrt(D)) / 2
        if p q = N and p, q prime:
            return (p, q)
    return FAIL

