"""Algorithm C/D: reading the Carmichael exponent, then recovering the factors."""

from __future__ import annotations

from math import gcd, isqrt
from typing import List, Optional, Tuple


def lcm(a: int, b: int) -> int:
    return 0 if a == 0 or b == 0 else a // gcd(a, b) * b


def power_sum_mod(N: int, k: int) -> int:
    total = 0
    for a in range(1, N + 1):
        total = (total + pow(a, k, N)) % N
    return total


def readout(N: int, k: int) -> int:
    return gcd(power_sum_mod(N, k), N)


def read_carmichael_exponent(N: int, k_max: Optional[int] = None) -> Optional[int]:
    """lambda(N) = least k > 0 with g_N(k) = 1.

    Correctness: the read-out is trivial exactly on the multiples of lambda(N),
    and lambda(N) is the least positive period of k |-> g_N(k).  Cost:
    Theta(lambda(N) * N) modular operations -- the period-finding bottleneck.
    """
    limit = k_max if k_max is not None else N
    for k in range(1, limit + 1):
        if readout(N, k) == 1:
            return k
    return None


def divisors(n: int) -> List[int]:
    small, large = [], []
    for d in range(1, isqrt(n) + 1):
        if n % d == 0:
            small.append(d)
            if d != n // d:
                large.append(n // d)
    return small + large[::-1]


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def recover_factors(N: int, lam: int) -> Optional[Tuple[int, int]]:
    """Recover p, q from N = pq and lambda(N).

    Uses the exact identity  p + q + lambda(N) * gcd(p-1, q-1) = N + 1.
    The single unknown is g = gcd(p-1, q-1), a divisor of lambda(N); for each
    candidate g we set s = N + 1 - lambda*g and solve x^2 - s x + N = 0.
    The naive identity p + q = N - lambda + 1 (i.e. g = 1) provably never works
    for a product of two distinct odd primes.

    Cost: O(tau(lambda)) integer square roots, tau = number-of-divisors.
    """
    for g in divisors(lam):
        s = N + 1 - lam * g
        if s <= 0:
            continue
        disc = s * s - 4 * N
        if disc < 0:
            continue
        root = isqrt(disc)
        if root * root != disc or (s + root) % 2:
            continue
        p, q = (s + root) // 2, (s - root) // 2
        if p * q == N and is_prime(p) and is_prime(q):
            return (min(p, q), max(p, q))
    return None


if __name__ == "__main__":
    for N in (15, 35, 143, 9797):
        lam = read_carmichael_exponent(N)
        print(f"N = {N}: lambda = {lam}, factors = {recover_factors(N, lam)}")
